#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int base7Digits(ll x) {
    int digits = 1;
    while (x >= 7) {
        x /= 7;
        ++digits;
    }
    return digits;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    if (n <= 0 || m <= 0) {
        cout << 0;
        return 0;
    }

    int d1 = base7Digits(n - 1);
    int d2 = base7Digits(m - 1);

    if (d1 + d2 > 7) {
        cout << 0;
        return 0;
    }

    ll answer = 0;

    function<void(int, int, ll, ll)> dfs =
        [&](int position, int used, ll first, ll second) {
            if (position == d1 + d2) {
                if (first < n && second < m) {
                    ++answer;
                }
                return;
            }

            for (int digit = 0; digit < 7; ++digit) {
                if (used & (1 << digit)) continue;

                if (position < d1) {
                    dfs(position + 1, used | (1 << digit),
                        first * 7 + digit, second);
                } else {
                    dfs(position + 1, used | (1 << digit),
                        first, second * 7 + digit);
                }
            }
        };

    dfs(0, 0, 0, 0);
    cout << answer;

    return 0;
}

